enum WirePayment: Decodable {
    case csv(raw: String), xml(document: String)    // canonical: exhaustive switches
    private enum Key: String, CodingKey { case type, payload }
    init(from decoder: Decoder) throws {            // router: read the discriminator
        let c = try decoder.container(keyedBy: Key.self)
        switch try c.decode(String.self, forKey: .type) {
        case "csv": self = .csv(raw: try c.decode(String.self, forKey: .payload))
        case "xml": self = .xml(document: try c.decode(String.self, forKey: .payload))
        default: throw DecodingError.dataCorruptedError(forKey: .type, in: c,
                         debugDescription: "unknown wire format")   // invalid-message
        }
    }
}
